ntc_la:			ds 4
ntc_lb:			ds 4
ntc_lr:			ds 4
ntc_lt:			ds 4
ntc_lsgn:		db 0
ntc_lcnt:		db 0
ntc_ldst:		dw 0
ntc_lix:		dw 0

ntc_rg29_e:
			IF ($ < 65536) && (ntc_rg30_e - ntc_rg30 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg30:
;## kw_l_mov
;kw_l_mov, <src>, <dest>  - dest = src (4 bytes)
kw_l_mov:
			pop hl
			pop de
			ldi
			ldi
			ldi
			ldi
			ret

ntc_rg30_e:
			IF ($ < 65536) && (ntc_rg31_e - ntc_rg31 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg31:
;## ntc_ltoa ntc_ldata ntc_data
; Long at (HL) to text at DE, 0 at the end. jp (ix) back. Uses IY.
ntc_ltoa:
			ld (ntc_ldst), de
			ld de, ntc_la
			ldi
			ldi
			ldi
			ldi
			ld de, (ntc_ldst)
			ld a, (ntc_la+3)
			or a
			jp p, ntc_lta_pos
			ld a, '-'
			ld (de), a
			inc de
			ld hl, ntc_la
			xor a
			sub (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
			inc hl
			ld a, 0
			sbc a, (hl)
			ld (hl), a
ntc_lta_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_lpow10
ntc_lta_pow:
			ld a, (iy+0)
			or (iy+1)
			or (iy+2)
			or (iy+3)
			jr z, ntc_lta_last
			ld c, '0'
ntc_lta_sub:
			ld hl, ntc_la
			ld a, (hl)
			sub (iy+0)
			ld (ntc_lt), a
			inc hl
			ld a, (hl)
			sbc a, (iy+1)
			ld (ntc_lt+1), a
			inc hl
			ld a, (hl)
			sbc a, (iy+2)
			ld (ntc_lt+2), a
			inc hl
			ld a, (hl)
			sbc a, (iy+3)
			ld (ntc_lt+3), a
			jr c, ntc_lta_dig
			ld hl, (ntc_lt)
			ld (ntc_la), hl
			ld hl, (ntc_lt+2)
			ld (ntc_la+2), hl
			inc c
			jr ntc_lta_sub
ntc_lta_dig:
			ld a, c
			cp '0'
			jr nz, ntc_lta_out
			ld a, (ntc_lead)
			or a
			jr z, ntc_lta_skip
			ld a, c
ntc_lta_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_lta_skip:
			ld bc, 4
			add iy, bc
			jr ntc_lta_pow
ntc_lta_last:
			ld a, (ntc_la)
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_lpow10:		dd 1000000000, 100000000, 10000000, 1000000, 100000, 10000, 1000, 100, 10, 0

ntc_rg31_e:
			IF ($ < 65536) && (ntc_rg32_e - ntc_rg32 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg32:
;## kw_l_printvb ntc_ltoa ntc_printbuf
;kw_l_printvb, <long>  - Option VBPrint: a space (or the -), the digits, a space
kw_l_printvb:
			pop hl
			ld de, ntc_numbuf
			inc hl
			inc hl
			inc hl
			bit 7, (hl)
			dec hl
			dec hl
			dec hl
			jr nz, ntc_lpv_neg
			ld a, ' '
			ld (de), a
			inc de
ntc_lpv_neg:
			ld ix, ntc_lpv_done
			jp ntc_ltoa
ntc_lpv_done:
			ld a, ' '
			ld (de), a
			inc de
			xor a
			ld (de), a
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

ntc_rg32_e:
			IF ($ < 65536) && (ntc_rg33_e - ntc_rg33 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg33:
;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

ntc_rg33_e:
			IF ($ < 65536) && (ntc_rg34_e - ntc_rg34 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg34:
;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode
ntc_sinit:		db 0			; 1 once the screen is set up
ntc_sbpc:		db 2			; bytes per char  \
ntc_scols:		db 40			; columns          | from ntc_modetab
ntc_smask:		db #F0			; pen 1 pixel mask |
ntc_sshift:		db 4			; glyph bits/byte /
ntc_pgstk:		ds 32			; putglyph: the stack an interrupt uses between characters
ntc_pgstk_top:
ntc_noadv:		db 0			; 1 = draw without moving the cursor
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_pgrow:		db 0			; draw / scroll counter
ntc_pgaddr:		dw 0			; draw / scroll address
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 10			; matrix this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
	IF NTC_ROMLIB
ntc_uroff:		db 0			; (ROM) 1 = the upper ROM is off while the screen is read
	ENDIF
ntc_modetab:	db 4, 20, #C0, 2		; mode 0
				db 2, 40, #F0, 4		; mode 1
				db 1, 80, #FF, 8		; mode 2

; (ntc_plat_scroll, ntc_plat_cls: their own section - the ROM runs them from RAM)

ntc_rg34_e:
			IF ($ < 65536) && (ntc_rg35_e - ntc_rg35 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg35:
;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			sub 32
			jr c, ntc_pc_bad
			cp 95
			jr c, ntc_pc_ok
ntc_pc_bad:
			ld a, '?' - 32
ntc_pc_ok:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_font
			add hl, de
			ex de, hl
			; fall into ntc_plat_putglyph

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = 8 byte glyph, draw at the cursor, move on
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld a, (ntc_cury)
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			ld b, h
			ld c, l
			add hl, hl
			add hl, hl
			add hl, bc			; HL = row * 80
			ld a, (ntc_sbpc)
			ld b, a
			ld a, (ntc_curx)
			ld c, a
			xor a
ntc_pg_mul:
			add a, c
			djnz ntc_pg_mul		; A = column * bytes per char
			ld c, a
			ld b, #C0
			add hl, bc			; HL = #C000 + row*80 + col*bpc
			ld a, (ntc_sbpc)		; mode 1 (2 bytes a row) and 2 (1 byte): their own loops
			cp 2
			jr z, ntc_pg_m1
			dec a
			jr z, ntc_pg_m2
			ld b, 8					; mode 0: 4 bytes a row, 2 pixels each (pen 1: bits 7, 6)
ntc_pg_m0lp:
			ld a, (de)
			inc de
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			and #C0
			ld (hl), a
			dec hl
			dec hl
			dec hl
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m0lp
			jr ntc_pg_drawn
ntc_pg_m1:
			ld b, 8
ntc_pg_m1lp:
			ld a, (de)				; pen 1: pixels 0-3 in the high nibble, 4-7 next
			inc de
			ld c, a
			and #F0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			rlca
			rlca
			and #F0
			ld (hl), a
			dec hl
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m1lp
			jr ntc_pg_drawn
ntc_pg_m2:
			ld b, 8
ntc_pg_m2lp:
			ld a, (de)
			inc de
			ld (hl), a
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m2lp
ntc_pg_drawn:
			ld a, (ntc_nmode)		; normal mode: a waiting interrupt gets in after each
			or a					; character (drawing text is long), on a stack of its own
			jr z, ntc_pg_adv		; (SP may be the thread or the real stack here)
			ld (ntc_pgaddr), sp
			ld sp, ntc_pgstk_top
			ei
			nop
			di
			ld sp, (ntc_pgaddr)
ntc_pg_adv:
			ld a, (ntc_noadv)
			or a
			jr nz, ntc_pg_noadv
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do
ntc_pg_noadv:
			xor a
			ld (ntc_noadv), a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

ntc_rg35_e:
			IF ($ < 65536) && (ntc_rg36_e - ntc_rg36 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg36:
;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_mode - A = mode (0-2, 3 = 2). Gate array mode with both
; ROMs off, set text layout, clear screen
; ------------------------------------------------------------
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld (ntc_smode), a
			ld a, (ntc_sinit)
			or a
			jr nz, ntc_md_set
			; the first time: copy the CPC's own font (lower ROM, chars 32-126 at
			; #3900) into ntc_font. The copy runs from #C000 (screen RAM, cleared
			; just after), because the program itself can sit under the lower ROM
		IF NTC_ROMLIB
			jp ntc_fontcopy		; (ROM: it runs here - the lower ROM goes on, this one stays on)
		ELSE
			ld hl, ntc_fontcopy
			ld de, #C000
			ld bc, ntc_fontcopy_end - ntc_fontcopy
			ldir
			jp #C000
		ENDIF
ntc_md_set:
			ld a, (ntc_smode)
			ld c, a
		IF NTC_ROMLIB
			or #84				; (ROM: the upper ROM on)
		ELSE
			or #8C
		ENDIF
			ld b, #7F
			out (c), a
			ld a, 1
			ld (ntc_sinit), a
			ld a, c
			add a, a
			add a, a
			ld c, a
			ld b, 0
			ld hl, ntc_modetab
			add hl, bc
			ld de, ntc_sbpc
			ld bc, 4
			ldir
			jp ntc_plat_cls

; copied to #C000 and run there (no jumps inside: it runs at any address)
ntc_fontcopy:
		IF NTC_ROMLIB
			ld bc, #7F80		; lower ROM on, upper ROM (this one) on
		ELSE
			ld bc, #7F88		; lower ROM on, upper ROM off
		ENDIF
			out (c), c
			ld hl, #3900		; the firmware's character matrices, from char 32
			ld de, ntc_font
			ld bc, 95 * 8
			ldir
		IF NTC_ROMLIB
			ld bc, #7F84		; lower ROM off again
		ELSE
			ld bc, #7F8C		; both ROMs off again
		ENDIF
			out (c), c
			jp ntc_md_set
ntc_fontcopy_end:

ntc_rg36_e:
			IF ($ < 65536) && (ntc_rg37_e - ntc_rg37 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg37:
;## ntc_plat_scroll ntc_plat_data ntc_data @shared @romram
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-24 up one, clear row 24
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, 24
			ld (ntc_cury), a
			ld a, (ntc_nmode)		; normal mode: interrupts in during the long copy
			or a
			jr z, ntc_sc_open
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_sc_open:
		IF NTC_ROMLIB
			ld a, 1				; (ROM: the upper ROM off while the screen is read;
			ld (ntc_uroff), a	; the interrupt handler turns it on for its calls)
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
		ENDIF
			ld hl, #C000
			ld a, 8
ntc_sc_line:
			ld (ntc_pgrow), a
			ld (ntc_pgaddr), hl
			ld d, h
			ld e, l
			ld bc, 80
			add hl, bc
			ld bc, 24 * 80
			ldir
			ld h, d
			ld l, e
			ld (hl), 0
			inc de
			ld bc, 79
			ldir
			ld hl, (ntc_pgaddr)
			ld bc, #800
			add hl, bc
			ld a, (ntc_pgrow)
			dec a
			jr nz, ntc_sc_line
			di
		IF NTC_ROMLIB
			ld a, (ntc_smode)	; (ROM: the upper ROM on again)
			or #84
			ld b, #7F
			out (c), a
			xor a
			ld (ntc_uroff), a
		ENDIF
			ld a, (ntc_nmode)
			or a
			jr z, ntc_sc_close
			ld sp, (ntc_ip)
ntc_sc_close:
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - clear screen memory, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld a, (ntc_nmode)		; normal mode: interrupts in during the long copy
			or a
			jr z, ntc_cl_open
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_cl_open:
		IF NTC_ROMLIB
			ld a, 1				; (ROM: the upper ROM off - the fill reads the screen back)
			ld (ntc_uroff), a
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
		ENDIF
			ld hl, #C000
			ld de, #C001
			ld bc, #3FFF
			ld (hl), 0
			ldir
			di
		IF NTC_ROMLIB
			ld a, (ntc_smode)	; (ROM: the upper ROM on again)
			or #84
			ld b, #7F
			out (c), a
			xor a
			ld (ntc_uroff), a
		ENDIF
			ld a, (ntc_nmode)
			or a
			jr z, ntc_cl_close
			ld sp, (ntc_ip)
ntc_cl_close:
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

ntc_rg37_e:
			IF ($ < 65536) && (ntc_rg38_e - ntc_rg38 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg38:
;## ntc_plat_irq ntc_plat_data ntc_data ntc_plat_irqh @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1)
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

ntc_rg38_e:
			IF ($ < 65536) && (ntc_rg39_e - ntc_rg39 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg39:
;## ntc_plat_irqh ntc_plat_data ntc_data @shared @romram
; the handler: runs on the real stack, between keywords. Counts ticks
; (300 a second). AF goes to AF', HL to RAM; interrupt classes' counting
; (ntc_irqv) is a call, keeping the other registers.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			ld hl, (ntc_ticks)
			inc hl
			ld (ntc_ticks), hl
			ld a, (ntc_hookon)	; an Interrupt hook: run it at the next safe point
			or a
			jr z, ntc_irq_nohook
			ld (ntc_hookpend), a
ntc_irq_nohook:
			ld hl, (ntc_irqv)		; interrupt classes (Option Class Interrupt): count them
			ld a, h
			or l
		IF NTC_ROMLIB
			call nz, ntc_irq_rom	; (the handler runs on the real stack)
		ELSE
			call nz, ntc_irq_jp		; (the handler runs on the real stack)
		ENDIF
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			ret
ntc_irq_jp:
			jp (hl)
		IF NTC_ROMLIB
; (ROM) the counting is in the main ROM of the set: the upper ROM on and the
; main ROM selected for the call (the screen code may have the upper ROM off,
; a far routine may have another ROM of the set in), then both as they were
ntc_irq_rom:
			push bc
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
			ld bc, (ntc_rx_s0)		; B = #DF, C = the main ROM's slot
			out (c), c
			call ntc_irq_jp
			ld bc, (ntc_rx_cur)		; the ROM that was in
			out (c), c
			ld a, (ntc_uroff)
			or a
			jr z, ntc_irq_ron
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
ntc_irq_ron:
			pop bc
			ret
		ENDIF

ntc_rg39_e:
			IF ($ < 65536) && (ntc_rg40_e - ntc_rg40 + $ > 49152)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #C000 (Option Memory Reserved #C000-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg40:
;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - before returning to the caller: interrupt handler
; out, upper ROM back on (lower off) if the screen was set up
; ------------------------------------------------------------
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)
			or a
			jr z, ntc_ex_rom
			ld hl, (ntc_irqold)
			ld (#0038), hl
			ld a, (ntc_irqold + 2)
			ld (#003A), a
			xor a
			ld (ntc_irqset), a
ntc_ex_rom:
			ld a, (ntc_sinit)
			or a
			jr z, ntc_ex_done
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
ntc_ex_done:
			jp (ix)


ntc_rg40_e:
ntc_end:				; the end of the program (and of its file)
glyph_20			equ ntc_font + 0		; " "
glyph_21			equ ntc_font + 8		; "!"
glyph_2D			equ ntc_font + 104		; "-"
glyph_31			equ ntc_font + 136		; "1"
glyph_32			equ ntc_font + 144		; "2"
glyph_33			equ ntc_font + 152		; "3"
glyph_37			equ ntc_font + 184		; "7"
glyph_3D			equ ntc_font + 232		; "="
glyph_61			equ ntc_font + 520		; "a"
glyph_62			equ ntc_font + 528		; "b"
glyph_6E			equ ntc_font + 624		; "n"
glyph_78			equ ntc_font + 704		; "x"
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack the caller's"
			DISPLAY "NTC memory: Reserved #C000-#FFFF (platform cpc)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
			IF (ntc_bssfrom < 65536) && (ntc_bssfrom + ntc_bss_size > 49152)	; fwdref-ok
ntc_bss		equ 65536		; after Option Memory Reserved #C000-#FFFF
			ELSE
ntc_bss		equ ntc_bssfrom
			ENDIF
			ASSERT ntc_bss + ntc_bss_size <= #10000, "out of memory: the arrays (after the last Option Memory Reserved / Paged range) do not fit below #10000"	; fwdref-ok
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 49152) || (ntc_bss >= 65536), "the program (or its arrays) reaches into the platform's reserved #C000-#FFFF (platform cpc: Option Memory Available frees it)"
